script.setup:
// Remix of two examples: Growing NCA (regrowing creatures) × WebGL Fluid. The creature lives in the fluid: the current
// drags its cells (all 16 channels) along and tears it, its colors bleed into the water as ink, and the cells' trained
// network keeps growing it back.
// Growing NCA: Mordvintsev, Randazzo, Niklasson, Levin (Distill 2020); model and pretrained weights from
// google-research/self-organising-systems (Apache-2.0), assets/growing_ca/models.zip, the "regenerating" runs.
// Fluid shaders adapted from Pavel Dobryakov's WebGL-Fluid-Simulation (MIT), ported to GLSL ES 3.00.
const gl = ctx.gl;
if (!gl.getExtension("EXT_color_buffer_float")) {
  throw new Error("This remix needs float render targets (EXT_color_buffer_float), which this GPU/browser doesn't offer.");
}
gl.getExtension("OES_texture_float_linear");

const VS = `#version 300 es
in vec2 a_position;
uniform vec2 texelSize;
out vec2 vUv; out vec2 vL; out vec2 vR; out vec2 vT; out vec2 vB;
void main() {
  vUv = a_position * 0.5 + 0.5;
  vL = vUv - vec2(texelSize.x, 0.0); vR = vUv + vec2(texelSize.x, 0.0);
  vT = vUv + vec2(0.0, texelSize.y); vB = vUv - vec2(0.0, texelSize.y);
  gl_Position = vec4(a_position, 0.0, 1.0);
}`;
const FS = (body) => `#version 300 es
precision highp float; precision highp sampler2D;
in vec2 vUv; in vec2 vL; in vec2 vR; in vec2 vT; in vec2 vB;
uniform vec2 texelSize;
out vec4 outColor;
${body}`;
const P = (body) => ctx.utils.createProgram(VS, FS(body));

const programs = {
  clear: P(`uniform sampler2D uTexture; uniform float value;
void main() { outColor = value * texture(uTexture, vUv); }`),
  splat: P(`uniform sampler2D uTarget; uniform float aspectRatio; uniform vec3 color; uniform vec2 point; uniform float radius;
void main() {
  vec2 p = vUv - point; p.x *= aspectRatio;
  vec3 splat = exp(-dot(p, p) / radius) * color;
  outColor = vec4(texture(uTarget, vUv).xyz + splat, 1.0);
}`),
  advection: P(`uniform sampler2D uVelocity; uniform sampler2D uSource; uniform float dt; uniform float dissipation;
void main() {
  vec2 coord = vUv - dt * texture(uVelocity, vUv).xy * texelSize;
  vec4 result = texture(uSource, coord);
  outColor = result / (1.0 + dissipation * dt);
}`),
  divergence: P(`uniform sampler2D uVelocity;
void main() {
  float L = texture(uVelocity, vL).x, R = texture(uVelocity, vR).x;
  float T = texture(uVelocity, vT).y, B = texture(uVelocity, vB).y;
  vec2 C = texture(uVelocity, vUv).xy;
  // walls: reflect the velocity at the edges
  if (vL.x < 0.0) L = -C.x; if (vR.x > 1.0) R = -C.x;
  if (vT.y > 1.0) T = -C.y; if (vB.y < 0.0) B = -C.y;
  outColor = vec4(0.5 * (R - L + T - B), 0.0, 0.0, 1.0);
}`),
  curl: P(`uniform sampler2D uVelocity;
void main() {
  float L = texture(uVelocity, vL).y, R = texture(uVelocity, vR).y;
  float T = texture(uVelocity, vT).x, B = texture(uVelocity, vB).x;
  outColor = vec4(0.5 * (R - L - T + B), 0.0, 0.0, 1.0);
}`),
  vorticity: P(`uniform sampler2D uVelocity; uniform sampler2D uCurl; uniform float curl; uniform float dt;
void main() {
  float L = texture(uCurl, vL).x, R = texture(uCurl, vR).x;
  float T = texture(uCurl, vT).x, B = texture(uCurl, vB).x, C = texture(uCurl, vUv).x;
  vec2 force = 0.5 * vec2(abs(T) - abs(B), abs(R) - abs(L));
  force /= length(force) + 0.0001;
  force *= curl * C; force.y *= -1.0;
  vec2 velocity = texture(uVelocity, vUv).xy + force * dt;
  outColor = vec4(clamp(velocity, -1000.0, 1000.0), 0.0, 1.0);
}`),
  pressure: P(`uniform sampler2D uPressure; uniform sampler2D uDivergence;
void main() {
  float L = texture(uPressure, vL).x, R = texture(uPressure, vR).x;
  float T = texture(uPressure, vT).x, B = texture(uPressure, vB).x;
  float divergence = texture(uDivergence, vUv).x;
  outColor = vec4((L + R + B + T - divergence) * 0.25, 0.0, 0.0, 1.0);
}`),
  gradient: P(`uniform sampler2D uPressure; uniform sampler2D uVelocity;
void main() {
  float L = texture(uPressure, vL).x, R = texture(uPressure, vR).x;
  float T = texture(uPressure, vT).x, B = texture(uPressure, vB).x;
  vec2 velocity = texture(uVelocity, vUv).xy - vec2(R - L, T - B);
  outColor = vec4(velocity, 0.0, 1.0);
}`),
};

// One fullscreen triangle, attribute 0 (createProgram binds a_position there).
const vao = gl.createVertexArray(), vbo = gl.createBuffer();
gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
gl.bindVertexArray(null);

function fbo(w, h, internalFormat, format) {
  const texture = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, texture);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  gl.texImage2D(gl.TEXTURE_2D, 0, internalFormat, w, h, 0, format, gl.HALF_FLOAT, null);
  const framebuffer = gl.createFramebuffer();
  gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
  gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, texture, 0);
  gl.viewport(0, 0, w, h); gl.clearColor(0, 0, 0, 1); gl.clear(gl.COLOR_BUFFER_BIT);
  gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  return { texture, framebuffer, width: w, height: h, texel: [1 / w, 1 / h] };
}
const pingPong = (w, h, internalFormat, format) => {
  const p = ctx.utils.createPingPong(w, h, { internalFormat, format, type: gl.HALF_FLOAT, filter: gl.LINEAR });
  return { p, width: w, height: h, texel: [1 / w, 1 / h] };
};
function size(resolution, w, h) {
  const aspect = w > h ? w / h : h / w;
  const lo = Math.round(resolution), hi = Math.round(resolution * aspect);
  return w > h ? [hi, lo] : [lo, hi];
}

const MODELS = 10, PER = 48 * 128 + 128 + 128 * 16 + 16;
const buf = await (await fetch(ctx.assets["nca-weights.bin"])).arrayBuffer();
const all = new Float32Array(buf);
if (all.length !== MODELS * PER) throw new Error(`nca-weights.bin: expected ${MODELS * PER} floats, got ${all.length}`);

// Pack the dense layers into float textures. w1: 128 wide (hidden unit j), 13 rows per model — row k holds inputs
// 4k..4k+3 for unit j, row 12 holds b1[j]. w2: 4 wide (output group), 129 rows per model — row j holds the 16 outputs
// of hidden unit j as four RGBA texels, row 128 holds b2.
const w1 = new Float32Array(128 * 13 * MODELS * 4), w2 = new Float32Array(4 * 129 * MODELS * 4);
for (let m = 0; m < MODELS; m++) {
  const o = m * PER, W1 = o, B1 = o + 6144, W2 = o + 6272, B2 = o + 8320;
  for (let k = 0; k < 12; k++) for (let j = 0; j < 128; j++) for (let c = 0; c < 4; c++)
    w1[((m * 13 + k) * 128 + j) * 4 + c] = all[W1 + (4 * k + c) * 128 + j];
  for (let j = 0; j < 128; j++) w1[((m * 13 + 12) * 128 + j) * 4] = all[B1 + j];
  for (let j = 0; j < 129; j++) for (let g = 0; g < 4; g++) for (let c = 0; c < 4; c++)
    w2[((m * 129 + j) * 4 + g) * 4 + c] = j < 128 ? all[W2 + j * 16 + 4 * g + c] : all[B2 + 4 * g + c];
}
const tex = (w, h, data) => ctx.utils.uploadDataTexture(gl, null, w, h, data, { internalFormat: gl.RGBA32F, format: gl.RGBA, type: gl.FLOAT, filter: gl.NEAREST });
const w1Tex = tex(128, 13 * MODELS, w1), w2Tex = tex(4, 129 * MODELS, w2);

const N = 80; // the grid: 16 channels per cell in four RGBA32F textures; row 0 is the top of the picture
const HEAD = `#version 300 es
precision highp float;
precision highp int;
precision highp sampler2D;
in vec2 v_uv;
`;
// One NCA step, before alive masking: perceive (identity + rotated Sobel per channel, zero padding as in TF 'SAME'),
// 48 -> 128 ReLU -> 16, and add the update to roughly half the cells (fire rate 0.5, step size 1).
const updateFs = HEAD + `
uniform sampler2D m_s0, m_s1, m_s2, m_s3, m_w1, m_w2;
uniform float m_model, m_seed, m_cos, m_sin;
layout(location = 0) out vec4 o0;
layout(location = 1) out vec4 o1;
layout(location = 2) out vec4 o2;
layout(location = 3) out vec4 o3;
uint hash(uvec3 v) {
  v = v * 1664525u + 1013904223u;
  v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
  v ^= v >> 16u;
  v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
  return v.x ^ v.y ^ v.z;
}
vec4 S(int t, ivec2 q) {
  if (q.x < 0 || q.y < 0 || q.x >= ${N} || q.y >= ${N}) return vec4(0.0);
  if (t == 0) return texelFetch(m_s0, q, 0);
  if (t == 1) return texelFetch(m_s1, q, 0);
  if (t == 2) return texelFetch(m_s2, q, 0);
  return texelFetch(m_s3, q, 0);
}
void main() {
  ivec2 p = ivec2(gl_FragCoord.xy);
  float y[48];
  vec4 self[4];
  for (int t = 0; t < 4; t++) {
    vec4 gx = vec4(0.0), gy = vec4(0.0);
    for (int dy = -1; dy <= 1; dy++) for (int dx = -1; dx <= 1; dx++) {
      vec4 v = S(t, p + ivec2(dx, dy));
      // Sobel / 8: dx = [[-1,0,1],[-2,0,2],[-1,0,1]] / 8, dy its transpose (rows run down the picture).
      gx += v * float(dx) * (dy == 0 ? 0.25 : 0.125);
      gy += v * float(dy) * (dx == 0 ? 0.25 : 0.125);
      if (dx == 0 && dy == 0) self[t] = v;
    }
    vec4 rx = m_cos * gx - m_sin * gy, ry = m_sin * gx + m_cos * gy;
    for (int c = 0; c < 4; c++) {
      int ch = t * 4 + c;
      y[ch * 3] = self[t][c]; y[ch * 3 + 1] = rx[c]; y[ch * 3 + 2] = ry[c];
    }
  }
  vec4 x4[12];
  for (int k = 0; k < 12; k++) x4[k] = vec4(y[4 * k], y[4 * k + 1], y[4 * k + 2], y[4 * k + 3]);
  int b1 = int(m_model) * 13, b2 = int(m_model) * 129;
  vec4 d0 = texelFetch(m_w2, ivec2(0, b2 + 128), 0), d1 = texelFetch(m_w2, ivec2(1, b2 + 128), 0);
  vec4 d2 = texelFetch(m_w2, ivec2(2, b2 + 128), 0), d3 = texelFetch(m_w2, ivec2(3, b2 + 128), 0);
  for (int j = 0; j < 128; j++) {
    float h = texelFetch(m_w1, ivec2(j, b1 + 12), 0).x;
    for (int k = 0; k < 12; k++) h += dot(x4[k], texelFetch(m_w1, ivec2(j, b1 + k), 0));
    h = max(h, 0.0);
    if (h == 0.0) continue;
    d0 += h * texelFetch(m_w2, ivec2(0, b2 + j), 0);
    d1 += h * texelFetch(m_w2, ivec2(1, b2 + j), 0);
    d2 += h * texelFetch(m_w2, ivec2(2, b2 + j), 0);
    d3 += h * texelFetch(m_w2, ivec2(3, b2 + j), 0);
  }
  float fire = float(hash(uvec3(p, uint(m_seed))) & 0xffffu) / 65536.0 < 0.5 ? 1.0 : 0.0;
  o0 = self[0] + d0 * fire; o1 = self[1] + d1 * fire; o2 = self[2] + d2 * fire; o3 = self[3] + d3 * fire;
}`;
// Alive masking: a cell lives only if some 3x3 neighbor had alpha > 0.1 both before and after the step.
// The brush (damage) clears cells here too.
const maskFs = HEAD + `
uniform sampler2D m_old, m_t0, m_t1, m_t2, m_t3;
uniform vec4 m_pen; // x, y in cells, radius, on
layout(location = 0) out vec4 o0;
layout(location = 1) out vec4 o1;
layout(location = 2) out vec4 o2;
layout(location = 3) out vec4 o3;
void main() {
  ivec2 p = ivec2(gl_FragCoord.xy);
  float pre = 0.0, post = 0.0;
  for (int dy = -1; dy <= 1; dy++) for (int dx = -1; dx <= 1; dx++) {
    ivec2 q = p + ivec2(dx, dy);
    if (q.x < 0 || q.y < 0 || q.x >= ${N} || q.y >= ${N}) continue;
    pre = max(pre, texelFetch(m_old, q, 0).a);
    post = max(post, texelFetch(m_t0, q, 0).a);
  }
  float alive = pre > 0.1 && post > 0.1 ? 1.0 : 0.0;
  if (m_pen.w > 0.0 && distance(vec2(p) + 0.5, m_pen.xy) < m_pen.z) alive = 0.0;
  o0 = texelFetch(m_t0, p, 0) * alive; o1 = texelFetch(m_t1, p, 0) * alive;
  o2 = texelFetch(m_t2, p, 0) * alive; o3 = texelFetch(m_t3, p, 0) * alive;
}`;
// Current: where the water runs fast past a cell, it washes the cell away (all 16 channels). Moving the cells' states
// with the flow instead smears them, and the smeared pieces grow into a mess; washing away is the damage the models
// were trained to heal. m_flow turns sim texels/s into cells/s.
const washFs = HEAD + `
uniform sampler2D m_s0, m_s1, m_s2, m_s3, m_vel;
uniform vec2 m_res, m_off, m_flow;
uniform float m_scale, m_seed;
layout(location = 0) out vec4 o0;
layout(location = 1) out vec4 o1;
layout(location = 2) out vec4 o2;
layout(location = 3) out vec4 o3;
float rnd(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233)) + m_seed) * 43758.5453); }
void main() {
  ivec2 p = ivec2(gl_FragCoord.xy);
  vec2 px = m_off + (vec2(p) + 0.5) * m_scale;
  vec2 v = texture(m_vel, vec2(px.x / m_res.x, 1.0 - px.y / m_res.y)).xy * m_flow;
  float keep = length(v) > 40.0 + 50.0 * rnd(vec2(p)) ? 0.0 : 1.0;
  o0 = texelFetch(m_s0, p, 0) * keep; o1 = texelFetch(m_s1, p, 0) * keep;
  o2 = texelFetch(m_s2, p, 0) * keep; o3 = texelFetch(m_s3, p, 0) * keep;
}`;
// Ink: the creature's colors seep into the dye wherever it is.
const inkFs = HEAD + `
uniform sampler2D m_s0, m_dye, m_vel;
uniform vec2 m_res, m_off, m_flow;
uniform float m_scale, m_amount;
out vec4 outColor;
void main() {
  vec2 uv = v_uv;
  vec2 c = (vec2(uv.x * m_res.x, (1.0 - uv.y) * m_res.y) - m_off) / m_scale;
  ivec2 q = ivec2(floor(c));
  vec4 cell = (q.x < 0 || q.y < 0 || q.x >= ${N} || q.y >= ${N}) ? vec4(0.0) : texelFetch(m_s0, q, 0);
  vec3 ink = clamp(cell.rgb, 0.0, 1.0) * (cell.a > 0.1 ? 1.0 : 0.0);
  float speed = length(texture(m_vel, uv).xy * m_flow);
  outColor = vec4(texture(m_dye, uv).rgb + ink * m_amount * (0.004 + smoothstep(15.0, 60.0, speed)), 1.0);
}`;
// Drawing: the water (dye, lit as a height field) on a dark background, the cells on top as rounded tiles.
const viewFs = HEAD + `
uniform sampler2D m_s0, m_dye;
uniform vec2 m_res, m_off, m_dyeTexel;
uniform float m_scale;
uniform vec3 m_bg;
out vec4 outColor;
vec4 cell(ivec2 q) {
  if (q.x < 0 || q.y < 0 || q.x >= ${N} || q.y >= ${N}) return vec4(0.0);
  return texelFetch(m_s0, q, 0);
}
void main() {
  vec2 uv = gl_FragCoord.xy / m_res;
  vec3 d = texture(m_dye, uv).rgb;
  vec3 l = texture(m_dye, uv - vec2(m_dyeTexel.x, 0.0)).rgb, r = texture(m_dye, uv + vec2(m_dyeTexel.x, 0.0)).rgb;
  vec3 t = texture(m_dye, uv + vec2(0.0, m_dyeTexel.y)).rgb, b = texture(m_dye, uv - vec2(0.0, m_dyeTexel.y)).rgb;
  vec3 n = normalize(vec3(length(r) - length(l), length(t) - length(b), length(m_dyeTexel)));
  d *= clamp(n.z + 0.7, 0.7, 1.0);
  vec2 cuv = uv - 0.5; cuv.x *= m_res.x / m_res.y;
  vec3 bg = m_bg * (1.0 - 0.35 * smoothstep(0.2, 1.0, length(cuv)));
  float da = clamp(max(d.r, max(d.g, d.b)), 0.0, 1.0);
  vec3 col = bg * (1.0 - da) + d;
  vec2 px = vec2(gl_FragCoord.x, m_res.y - gl_FragCoord.y);
  vec2 c = (px - m_off) / m_scale;
  vec4 v = cell(ivec2(floor(c)));
  float a = clamp(v.a, 0.0, 1.0);
  float gap = m_scale > 5.0 ? 0.06 : 0.0, rr = 0.24, aa = 1.0 / m_scale;
  vec2 q = abs(fract(c) - 0.5) - (0.5 - gap - rr);
  float sd = length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - rr;
  float tile = m_scale > 5.0 ? smoothstep(aa, -aa, sd) : 1.0;
  vec3 rgb = clamp(v.rgb, 0.0, 1.0) * (1.0 + 0.08 * (0.5 - fract(c).y));
  col = col * (1.0 - a * tile) + rgb * tile;
  outColor = vec4(col, 1.0);
}`;
const pp = (count) => ctx.utils.createPingPong(N, N, { internalFormat: gl.RGBA32F, format: gl.RGBA, type: gl.FLOAT, filter: gl.NEAREST, count });
const s = ctx.state;
Object.assign(s, {
  N, w1Tex, w2Tex, programs, vao, fbo, pingPong, size,
  update: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, updateFs),
  mask: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, maskFs),
  wash: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, washFs),
  ink: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, inkFs),
  view: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, viewFs),
  world: pp(4), temp: pp(4), acc: 0, seed: 1, model: -1, targets: null, key: "", splats: [], gustAt: 3,
  zeros: new Float32Array(N * N * 4), px: new Float32Array(N * N * 4),
});
// A single seed cell in the middle: alpha and every hidden channel set to 1.
s.reseed = () => {
  const mid = ((s.N >> 1) * s.N + (s.N >> 1)) * 4;
  for (const target of [s.world.read(), s.world.write()]) target.textures.forEach((t, i) => {
    const data = s.zeros.slice();
    if (i === 0) data[mid + 3] = 1; else data.fill(1, mid, mid + 4);
    gl.bindTexture(gl.TEXTURE_2D, t);
    gl.texSubImage2D(gl.TEXTURE_2D, 0, 0, 0, s.N, s.N, gl.RGBA, gl.FLOAT, data);
  });
  s.gustAt = ctx.time + 4;
};
// Draws one fluid pass into `target` (null = screen). Program must already have its uniforms set.
s.blit = (target, w, h) => {
  gl.bindFramebuffer(gl.FRAMEBUFFER, target);
  gl.viewport(0, 0, w, h);
  gl.bindVertexArray(vao);
  gl.drawArrays(gl.TRIANGLES, 0, 3);
};
s.use = (program, textures, uniforms) => {
  gl.useProgram(program);
  let unit = 0;
  for (const [name, tex] of Object.entries(textures)) ctx.utils.bindTexture(program, name, tex, unit++);
  ctx.utils.setUniforms(program, uniforms);
};
s.color = (hue) => {
  const h = ((hue % 1) + 1) % 1, i = Math.floor(h * 6), f = h * 6 - i, q = 1 - f;
  const rgb = [[1, f, 0], [q, 1, 0], [0, 1, f], [0, q, 1], [f, 0, 1], [1, 0, q]][i % 6];
  return rgb.map((c) => c * 0.15);
};

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, P = s.programs, N = s.N;
const [W, H] = ctx.resolution;
const aspect = W / H;
const model = Math.round(u.u_model);
if (model !== s.model || u.u_reseed) { s.model = model; s.reseed(); }
// Frame the grown creature (about 40 cells) to about 60% of the shorter side, centered, in any aspect.
const scale = Math.min(W, H) / 68, ox = (W - N * scale) / 2, oy = (H - N * scale) / 2;

// Fluid targets follow the canvas shape: velocity at 128, dye at 768 on the shorter side.
const key = `${W}x${H}`;
if (s.key !== key) {
  s.key = key;
  const [sw, sh] = s.size(128, W, H), [dw, dh] = s.size(768, W, H);
  s.targets = {
    sim: [sw, sh], simTexel: [1 / sw, 1 / sh],
    dye: s.pingPong(dw, dh, gl.RGBA16F, gl.RGBA),
    velocity: s.pingPong(sw, sh, gl.RG16F, gl.RG),
    pressure: s.pingPong(sw, sh, gl.R16F, gl.RED),
    divergence: s.fbo(sw, sh, gl.R16F, gl.RED),
    curl: s.fbo(sw, sh, gl.R16F, gl.RED),
  };
}
const T = s.targets, [sw, sh] = T.sim;
const dt = Math.min(ctx.dt || 1 / 60, 1 / 30);
const radius = u.u_radius / 100;
const splat = (x, y, dx, dy, color, r = 1) => {
  const rad = (aspect > 1 ? radius * aspect : radius) * r;
  s.use(P.splat, { uTarget: T.velocity.p.read().texture }, { aspectRatio: aspect, point: [x, y], color: [dx, dy, 0], radius: rad, texelSize: T.simTexel });
  s.blit(T.velocity.p.write().framebuffer, sw, sh); T.velocity.p.swap();
  if (color) {
    s.use(P.splat, { uTarget: T.dye.p.read().texture }, { aspectRatio: aspect, point: [x, y], color, radius: rad, texelSize: T.dye.texel });
    s.blit(T.dye.p.write().framebuffer, T.dye.width, T.dye.height); T.dye.p.swap();
  }
};

// Input: drag to stir the water. Gusts: every few seconds a jet sweeps across the creature from a random side.
const hue = ctx.time * 0.1;
if (ctx.mouseDown) {
  const [mx, my] = ctx.mouse, [px, py] = ctx.mousePrev;
  const dx = (mx - px) * (aspect < 1 ? aspect : 1), dy = (py - my) * (aspect > 1 ? 1 / aspect : 1);
  if (dx !== 0 || dy !== 0) splat(mx, 1 - my, dx * u.u_force, dy * u.u_force, s.color(hue).map((c) => c * 0.6));
}
if (u.u_gusts) {
  // a slow background swirl so the water never quite settles
  const t = ctx.time * 0.35;
  splat(0.5 + 0.38 * Math.cos(t), 0.5 + 0.38 * Math.sin(t * 1.3), -Math.sin(t) * 60, Math.cos(t * 1.3) * 60, null, 0.8);
  if (ctx.time > s.gustAt && s.alive > 150) {
    s.gustAt = ctx.time + 3.2 + Math.random() * 1.6;
    const a = Math.random() * Math.PI * 2, along = [Math.cos(a), Math.sin(a)];
    // start a little before the creature and push straight through it, in a short burst of splats
    for (let k = 0; k < 6; k++) {
      const o = -0.2 + k * 0.07, side = (Math.random() - 0.5) * 0.08;
      s.splats.push({ x: 0.5 + along[0] * o / (aspect > 1 ? aspect : 1) - along[1] * side, y: 0.5 + along[1] * o * (aspect < 1 ? aspect : 1) + along[0] * side,
        dx: along[0] * u.u_force * 0.18, dy: along[1] * u.u_force * 0.18, color: null, r: 0.7 });
    }
  }
}
if (u.u_splash) for (let i = 0; i < 8; i++) {
  const a = Math.random() * Math.PI * 2;
  s.splats.push({ x: 0.5 + (Math.random() - 0.5) * 0.4, y: 0.5 + (Math.random() - 0.5) * 0.4, dx: Math.cos(a) * 1400, dy: Math.sin(a) * 1400, color: null, r: 1 });
}
for (const p of s.splats) splat(p.x, p.y, p.dx, p.dy, p.color, p.r);
s.splats.length = 0;

// Fluid step: curl -> vorticity confinement -> divergence -> pressure (Jacobi) -> subtract gradient -> advect velocity.
gl.disable(gl.BLEND);
s.use(P.curl, { uVelocity: T.velocity.p.read().texture }, { texelSize: T.simTexel });
s.blit(T.curl.framebuffer, sw, sh);
s.use(P.vorticity, { uVelocity: T.velocity.p.read().texture, uCurl: T.curl.texture }, { texelSize: T.simTexel, curl: u.u_curl, dt });
s.blit(T.velocity.p.write().framebuffer, sw, sh); T.velocity.p.swap();
s.use(P.divergence, { uVelocity: T.velocity.p.read().texture }, { texelSize: T.simTexel });
s.blit(T.divergence.framebuffer, sw, sh);
s.use(P.clear, { uTexture: T.pressure.p.read().texture }, { value: 0.8, texelSize: T.simTexel });
s.blit(T.pressure.p.write().framebuffer, sw, sh); T.pressure.p.swap();
for (let i = 0; i < 20; i++) {
  s.use(P.pressure, { uPressure: T.pressure.p.read().texture, uDivergence: T.divergence.texture }, { texelSize: T.simTexel });
  s.blit(T.pressure.p.write().framebuffer, sw, sh); T.pressure.p.swap();
}
s.use(P.gradient, { uPressure: T.pressure.p.read().texture, uVelocity: T.velocity.p.read().texture }, { texelSize: T.simTexel });
s.blit(T.velocity.p.write().framebuffer, sw, sh); T.velocity.p.swap();
s.use(P.advection, { uVelocity: T.velocity.p.read().texture, uSource: T.velocity.p.read().texture }, { texelSize: T.simTexel, dt, dissipation: u.u_velocity });
s.blit(T.velocity.p.write().framebuffer, sw, sh); T.velocity.p.swap();

// NCA passes run on the N×N grid.
const quad = (prog, target, inputs, extra) => {
  gl.bindFramebuffer(gl.FRAMEBUFFER, target.framebuffer);
  gl.viewport(0, 0, N, N);
  gl.useProgram(prog);
  inputs.forEach(([name, t], i) => ctx.utils.bindTexture(prog, name, t, i));
  ctx.utils.drawFullscreen(prog, extra);
};
const cellTex = () => s.world.read().textures;
// Velocity (sim texels/s) in cells/s: W/sw canvas px per texel, 1/scale cells per px.
const flow = [u.u_current * W / sw / scale, u.u_current * H / sh / scale];
s.acc = Math.min(s.acc + Math.min(ctx.dt, 0.1) * u.u_speed, 8);
const steps = Math.floor(s.acc);
s.acc -= steps;
for (let i = 0; i < steps; i++) {
  const r = cellTex(), t = s.temp.write();
  quad(s.update, t, [["m_s0", r[0]], ["m_s1", r[1]], ["m_s2", r[2]], ["m_s3", r[3]], ["m_w1", s.w1Tex], ["m_w2", s.w2Tex]],
    { m_model: model, m_seed: (s.seed = (s.seed + 1) % 1e6), m_cos: 1, m_sin: 0 });
  quad(s.mask, s.world.write(), [["m_old", r[0]], ["m_t0", t.textures[0]], ["m_t1", t.textures[1]], ["m_t2", t.textures[2]], ["m_t3", t.textures[3]]], { m_pen: [0, 0, 0, 0] });
  s.world.swap();
}

// Ink seeps from the creature into the water, then the water carries it.
gl.useProgram(s.ink);
ctx.utils.bindTexture(s.ink, "m_s0", cellTex()[0], 0);
ctx.utils.bindTexture(s.ink, "m_dye", T.dye.p.read().texture, 1);
ctx.utils.bindTexture(s.ink, "m_vel", T.velocity.p.read().texture, 2);
gl.bindFramebuffer(gl.FRAMEBUFFER, T.dye.p.write().framebuffer);
gl.viewport(0, 0, T.dye.width, T.dye.height);
ctx.utils.drawFullscreen(s.ink, { m_res: [W, H], m_off: [ox, oy], m_scale: scale, m_amount: u.u_ink * dt * 60, m_flow: flow });
T.dye.p.swap();
s.use(P.advection, { uVelocity: T.velocity.p.read().texture, uSource: T.dye.p.read().texture }, { texelSize: T.simTexel, dt, dissipation: u.u_dye });
s.blit(T.dye.p.write().framebuffer, T.dye.width, T.dye.height); T.dye.p.swap();

// Then the current washes off the cells it ran past (after their color went into the water).
if (u.u_current > 0) {
  const r = cellTex();
  quad(s.wash, s.world.write(), [["m_s0", r[0]], ["m_s1", r[1]], ["m_s2", r[2]], ["m_s3", r[3]], ["m_vel", T.velocity.p.read().texture]],
    { m_res: [W, H], m_off: [ox, oy], m_scale: scale, m_flow: flow, m_seed: ctx.frame % 997 });
  s.world.swap();
}

gl.bindFramebuffer(gl.FRAMEBUFFER, null);
gl.viewport(0, 0, W, H);
gl.useProgram(s.view);
ctx.utils.bindTexture(s.view, "m_s0", cellTex()[0], 0);
ctx.utils.bindTexture(s.view, "m_dye", T.dye.p.read().texture, 1);
ctx.utils.drawFullscreen(s.view, { m_res: [W, H], m_off: [ox, oy], m_scale: scale, m_dyeTexel: T.dye.texel, m_bg: u.u_bg });

// Twice a second, count living cells (alpha > 0.1); if the current swept everything away, start again from a seed.
if (ctx.frame % 30 === 0) {
  gl.bindFramebuffer(gl.FRAMEBUFFER, s.world.read().framebuffer);
  gl.readBuffer(gl.COLOR_ATTACHMENT0);
  gl.readPixels(0, 0, N, N, gl.RGBA, gl.FLOAT, s.px);
  gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  let alive = 0;
  for (let i = 0; i < N * N; i++) if (s.px[i * 4 + 3] > 0.1) alive++;
  s.alive = alive;
  s.deadSince = alive ? null : s.deadSince ?? ctx.time;
  if (s.deadSince != null && ctx.time - s.deadSince > 1) s.reseed();
}
ctx.publish("living cells", s.alive ?? 0);
